   g_table(["Propiedad", "Fórmula", "Ejemplo"], [["Producto de igual base", "aᵐ · aⁿ = aᵐ⁺ⁿ", "2³ · 2⁴ = 2⁷ = 128"], ["Cociente de igual base", "aᵐ / aⁿ = aᵐ⁻ⁿ", "5⁶ / 5⁴ = 5² = 25"], ["Potencia de una potencia", "(aᵐ)ⁿ = aᵐ·ⁿ", "(3²)³ = 3⁶ = 729"],
                                                 ["Potencia de un producto", "(a·b)ⁿ = aⁿ · bⁿ", "(2·5)² = 4 · 25 = 100"], ["Exponente negativo", "a⁻ⁿ = 1 / aⁿ", "5⁻² = 1/25 = 0,04"]]),
   g_h2("3. Exponentes fraccionarios"),
