   g_steps(["9^(1/2) = √9 = 3", "8^(2/3) = (∛8)² = 2² = 4", "16^(3/4) = (⁴√16)³ = 2³ = 8"]),
   g_h2("4. Qué es una raíz"),
   g_formula("ⁿ√x = y &nbsp;&nbsp;⇔&nbsp;&nbsp; yⁿ = x"),
   g_p("La raíz cuadrada de 49 es 7 porque 7² = 49. La raíz cúbica de −27 es −3, porque (−3)³ = −27: las raíces de índice impar existen para números negativos, pero las de índice par no (en los números reales)."),
   g_table(["Cuadrados perfectos", "Cubos perfectos"], [["1, 4, 9, 16, 25, 36, 49, 64, 81, 100", "1, 8, 27, 64, 125, 216, 343, 512, 729, 1.000"], ["121, 144, 169, 196, 225", "—"]]),
   g_h2("5. Simplificar radicales"),
